import { Component, computed, inject, signal } from '@angular/core';
import { CommonModule } from '@angular/common';
import { ActivatedRoute, Router, RouterLink } from '@angular/router';
import { switchMap } from 'rxjs';

import { AuthService } from '../../../../services/auth.service';
import { extractErrorMessage } from '../../../../shared/utils/error-utils';
import { SolicitudService } from '../../../../shared/services/solicitud.service';
import { TramiteService } from '../../../../shared/services/tramite.service';
import { ToastService } from '../../../../shared/services/toast.service';
import { ToastContainerComponent } from '../../../../shared/components/toast-container/toast-container.component';
import { NavigationHistoryService } from '../../../../services/navigation-history.service';
import { PdfViewerComponent } from '../../../../shared/components/pdf-viewer/pdf-viewer.component';
import {
  Solicitud,
  SolicitudTramite,
  TramiteAprobacionResponse,
} from '../../../../shared/models/solicitud.model';

@Component({
  selector: 'app-tramite-revision',
  imports: [CommonModule, RouterLink, ToastContainerComponent, PdfViewerComponent],
  templateUrl: './tramite-revision.component.html',
})
export class TramiteRevisionComponent {
  private readonly route = inject(ActivatedRoute);
  private readonly router = inject(Router);
  private readonly solicitudService = inject(SolicitudService);
  private readonly tramiteService = inject(TramiteService);
  private readonly authService = inject(AuthService);
  private readonly toastService = inject(ToastService);
  private readonly navHistory = inject(NavigationHistoryService);

  readonly folio = signal<string>('');
  readonly solicitud = signal<Solicitud | null>(null);
  readonly tramites = signal<SolicitudTramite[]>([]);
  readonly loading = signal(false);
  readonly error = signal<string | null>(null);

  readonly tramiteARechazar = signal<SolicitudTramite | null>(null);
  readonly observacionesRechazo = signal('');
  readonly mostrarVisor = signal(false);
  readonly selectedDocId = signal<number | null>(null);
  readonly selectedDocNombre = signal<string | null>(null);

  readonly puedeAprobar = computed(() => {
    const role = this.authService.currentUser()?.role;
    return role === 'ejecutivo' || role === 'admin';
  });

  goBack(): void {
    this.router.navigateByUrl(this.navHistory.getBackRoute('ejecutivo', 'autorizadas/asignar'));
  }

  constructor() {
    const folio = this.route.snapshot.paramMap.get('folio') ?? '';
    this.folio.set(folio);
    this.cargar();
  }

  cargar(): void {
    this.loading.set(true);
    this.error.set(null);
    const folio = this.folio();

    this.tramiteService.cargarDatosRevision(folio).subscribe({
      next: (data) => {
        this.solicitud.set(data.solicitud);
        this.tramites.set(data.tramites);
        this.loading.set(false);
      },
      error: (err) => {
        this.error.set(extractErrorMessage(err));
        this.loading.set(false);
      },
    });
  }

  puedeMarcarCompletado(t: SolicitudTramite): boolean {
    return this.puedeAprobar() && t.estado !== 'completado';
  }

  puedeRechazarTramite(t: SolicitudTramite): boolean {
    return this.puedeAprobar() && t.estado !== 'rechazado';
  }

  puedeMarcarPendiente(t: SolicitudTramite): boolean {
    return this.puedeAprobar() && t.estado !== 'pendiente';
  }

  marcarCompletado(t: SolicitudTramite): void {
    this.tramiteService
      .marcarTramiteCompletado(this.folio(), t.id)
      .pipe(
          switchMap(() => this.tramiteService.cargarDatosRevision(this.folio())),
      )
      .subscribe({
        next: (data) => {
          this.solicitud.set(data.solicitud);
          this.tramites.set(data.tramites);
          this.toastService.success(`El trámite "${t.nombre}" se ha completado correctamente.`);
        },
        error: (err) => {
          const errMsg = extractErrorMessage(err);
          this.error.set(errMsg);
          this.toastService.error(errMsg);
        },
      });
  }

  marcarPendiente(t: SolicitudTramite): void {
    this.tramiteService
      .marcarTramitePendiente(this.folio(), t.id)
      .pipe(
          switchMap(() => this.tramiteService.cargarDatosRevision(this.folio())),
      )
      .subscribe({
        next: (data) => {
          this.solicitud.set(data.solicitud);
          this.tramites.set(data.tramites);
          this.toastService.success(`El trámite "${t.nombre}" se ha marcado como pendiente.`);
        },
        error: (err) => {
          const errMsg = extractErrorMessage(err);
          this.error.set(errMsg);
          this.toastService.error(errMsg);
        },
      });
  }

  aprobar(t: SolicitudTramite): void {
    this.tramiteService
      .aprobarTramite(this.folio(), t.id)
      .pipe(
          switchMap(() => this.tramiteService.cargarDatosRevision(this.folio())),
      )
      .subscribe({
        next: (data) => {
          this.solicitud.set(data.solicitud);
          this.tramites.set(data.tramites);
          this.toastService.success(`El trámite "${t.nombre}" se ha aprobado correctamente.`);
        },
        error: (err) => {
          const errMsg = extractErrorMessage(err);
          this.error.set(errMsg);
          this.toastService.error(errMsg);
        },
      });
  }

  abrirModalRechazo(t: SolicitudTramite): void {
    this.tramiteARechazar.set(t);
    this.observacionesRechazo.set('');
  }

  cerrarModalRechazo(): void {
    this.tramiteARechazar.set(null);
    this.observacionesRechazo.set('');
  }

  cerrarModalRechazoConBackdrop(event: MouseEvent): void {
    if (event.target === event.currentTarget) {
      this.cerrarModalRechazo();
    }
  }

  confirmarRechazo(): void {
    const t = this.tramiteARechazar();
    if (!t) return;

    this.tramiteService
      .rechazarTramite(this.folio(), t.id, this.observacionesRechazo() || undefined)
      .pipe(
          switchMap(() => this.tramiteService.cargarDatosRevision(this.folio())),
      )
      .subscribe({
        next: (data) => {
          this.solicitud.set(data.solicitud);
          this.tramites.set(data.tramites);
          this.toastService.success(`El trámite "${t.nombre}" ha sido rechazado.`);
          this.cerrarModalRechazo();
        },
        error: (err) => {
          const errMsg = extractErrorMessage(err);
          this.error.set(errMsg);
          this.toastService.error(errMsg);
        },
      });
  }

  private actualizarTramite(data: TramiteAprobacionResponse): void {
    this.tramites.update((ts) =>
      ts.map((t) =>
        t.id === data.id
          ? {
              ...t,
              estado: data.estado,
              observaciones: data.observaciones ?? t.observaciones,
              fecha_completado: data.fechaCompletado ?? t.fecha_completado,
            }
          : t,
      ),
    );
  }

  estadoBadgeClass(estado: string): string {
    switch (estado) {
      case 'pendiente':
        return 'bg-secondary';
      case 'documento_subido':
        return 'bg-warning text-dark';
      case 'completado':
        return 'bg-success';
      case 'rechazado':
        return 'bg-danger';
      default:
        return 'bg-secondary';
    }
  }

  estadoLabel(estado: string): string {
    switch (estado) {
      case 'pendiente':
        return 'Pendiente';
      case 'documento_subido':
        return 'Documento subido';
      case 'completado':
        return 'Aprobado';
      case 'rechazado':
        return 'Rechazado';
      default:
        return estado;
    }
  }

  semaforoTramite(t: SolicitudTramite): { status: string; label: string; colorClass: string } {
    if (t.estado === 'completado') {
      return { status: 'completed', label: 'Completado', colorClass: 'bg-success' };
    }

    const dias = t.vigenciaDias;
    if (!dias) {
      return { status: 'none', label: 'Sin vigencia', colorClass: 'bg-secondary' };
    }

    const asignacion = new Date(t.fecha_asignacion.replace(' ', 'T') + 'Z');
    const ahora = new Date();
    const diffMs = ahora.getTime() - asignacion.getTime();
    const diasTranscurridos = Math.floor(diffMs / (1000 * 60 * 60 * 24));
    const diasRestantes = dias - diasTranscurridos;

    if (diasRestantes >= 21) {
      return { status: 'green', label: `${diasRestantes} días restantes`, colorClass: 'bg-success' };
    }
    if (diasRestantes >= 11) {
      return { status: 'yellow', label: `${diasRestantes} días restantes`, colorClass: 'bg-warning' };
    }
    if (diasRestantes >= 0) {
      return { status: 'red', label: `${diasRestantes} días restantes`, colorClass: 'bg-danger' };
    }
    return { status: 'overdue', label: `Vencido (hace ${Math.abs(diasRestantes)} días)`, colorClass: 'bg-danger' };
  }

  verDocumento(docId: number, nombre?: string): void {
    this.selectedDocId.set(docId);
    this.selectedDocNombre.set(nombre ?? null);
    this.mostrarVisor.set(true);
  }

  cerrarVisor(): void {
    this.mostrarVisor.set(false);
    this.selectedDocId.set(null);
    this.selectedDocNombre.set(null);
  }
}
